INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.4-Q1', 'analyse-fondamentale', 'outils', 1, 'Le ratio P/E (Price-to-Earnings) mesure :', '[{"id":"a","label":"La valorisation par rapport aux bénéfices"},{"id":"b","label":"La rentabilité des capitaux propres"},{"id":"c","label":"Le niveau d''endettement"},{"id":"d","label":"La liquidité"}]'::jsonb, 'a', 'P/E = Cours / BPA. Indique combien d''années de bénéfices sont payées.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.4-Q2', 'analyse-fondamentale', 'outils', 1, 'Le modèle DCF (Discounted Cash Flow) estime la valeur intrinsèque via :', '[{"id":"a","label":"Les flux de trésorerie futurs actualisés"},{"id":"b","label":"Le cours de bourse moyen"},{"id":"c","label":"Les volumes de transactions"},{"id":"d","label":"Le sentiment des analystes"}]'::jsonb, 'a', 'DCF = somme des FCF futurs actualisés + valeur terminale.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.4-Q3', 'analyse-fondamentale', 'outils', 1, 'L''analyse sectorielle vise à :', '[{"id":"a","label":"Identifier les tendances et défis spécifiques à un secteur"},{"id":"b","label":"Prédire le cours du pétrole"},{"id":"c","label":"Mesurer l''inflation"},{"id":"d","label":"Calculer le PIB"}]'::jsonb, 'a', 'Elle compare les performances au sein d''un secteur pour identifier leaders et laggards.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.4-Q4', 'analyse-fondamentale', 'outils', 1, 'L''analyse SWOT examine :', '[{"id":"a","label":"Les forces, faiblesses, opportunités et menaces"},{"id":"b","label":"Les salaires et les coûts"},{"id":"c","label":"Les taux d''intérêt et l''inflation"},{"id":"d","label":"Les volumes et la volatilité"}]'::jsonb, 'a', 'SWOT = outil stratégique d''évaluation qualitative.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.4-Q5', 'analyse-fondamentale', 'outils', 1, 'Un ratio D/E < 1 est généralement interprété comme :', '[{"id":"a","label":"Un endettement excessif"},{"id":"b","label":"Une santé financière raisonnable"},{"id":"c","label":"Une rentabilité faible"},{"id":"d","label":"Une liquidité insuffisante"}]'::jsonb, 'b', 'Moins de dette que de fonds propres = structure financière conservative.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.4-Q6', 'analyse-fondamentale', 'outils', 2, 'Le P/B (Price-to-Book) compare :', '[{"id":"a","label":"Le cours de bourse à la valeur comptable par action"},{"id":"b","label":"Le bénéfice net aux dividendes"},{"id":"c","label":"La dette aux revenus"},{"id":"d","label":"Le cours au flux de trésorerie"}]'::jsonb, 'a', 'Utile pour évaluer les entreprises à fort actif tangible (banques, industrie).', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.4-Q7', 'analyse-fondamentale', 'outils', 2, 'Dans un modèle DCF, le WACC représente :', '[{"id":"a","label":"Le taux de croissance des revenus"},{"id":"b","label":"Le coût moyen pondéré du capital"},{"id":"c","label":"Le bénéfice par action"},{"id":"d","label":"Le taux d''actualisation du risque pays"}]'::jsonb, 'b', 'WACC = coût moyen pondéré du capital, paramètre le plus sensible du DCF.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.4-Q8', 'analyse-fondamentale', 'outils', 2, 'Pourquoi le P/E d''Apple (28 en 2023) peut être considéré comme supérieur à la moyenne du secteur ?', '[{"id":"a","label":"Parce qu''Apple est en faillite"},{"id":"b","label":"Parce que la prime reflète la qualité, l''écosystème et la croissance des services"},{"id":"c","label":"Parce que le secteur tech a un P/E moyen de 50"},{"id":"d","label":"Parce que le P/E n''a pas d''importance"}]'::jsonb, 'b', 'Une prime est justifiée par des avantages concurrentiels durables.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.4-Q9', 'analyse-fondamentale', 'outils', 2, 'La comparaison Tesla vs Ford (P/E 50 vs 10) reflète :', '[{"id":"a","label":"Que Ford est toujours meilleur"},{"id":"b","label":"Des perspectives de croissance et de risque différentes"},{"id":"c","label":"Que Tesla est sous-évaluée"},{"id":"d","label":"Que le P/E est inutile"}]'::jsonb, 'b', 'Un P/E élevé = croissance attendue ; un P/E bas = maturité ou difficultés.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.4-Q10', 'analyse-fondamentale', 'outils', 2, 'L''analyse comparative (peer comparison) permet de :', '[{"id":"a","label":"Identifier les écarts de valorisation justifiés ou non"},{"id":"b","label":"Prédire les taux de change"},{"id":"c","label":"Mesurer l''inflation"},{"id":"d","label":"Calculer le PIB"}]'::jsonb, 'a', 'Comparer avec des pairs aide à détecter surévaluation ou sous-évaluation.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.4-Q11', 'analyse-fondamentale', 'outils', 3, 'Pourquoi le modèle DCF est-il particulièrement sensible au WACC ?', '[{"id":"a","label":"Parce que +1 % WACC = −15 à −20 % valorisation"},{"id":"b","label":"Parce que le WACC n''a pas d''impact"},{"id":"c","label":"Parce que le WACC est fixe"},{"id":"d","label":"Parce que le WACC remplace la croissance"}]'::jsonb, 'a', 'Le WACC est le paramètre le plus critique du DCF.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.4-Q12', 'analyse-fondamentale', 'outils', 2, 'Dans l''analyse SWOT de Netflix, « Base d''abonnés mondiale » est une :', '[{"id":"a","label":"Faiblesse"},{"id":"b","label":"Force"},{"id":"c","label":"Menace"},{"id":"d","label":"Opportunité"}]'::jsonb, 'b', 'C''est un avantage concurrentiel structurel.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.4-Q13', 'analyse-fondamentale', 'outils', 3, 'Pourquoi un multiple absolu (ex: P/E 30) peut être trompeur ?', '[{"id":"a","label":"Parce qu''il dépend du secteur et du cycle économique"},{"id":"b","label":"Parce que 30 est toujours cher"},{"id":"c","label":"Parce que les multiples ne servent à rien"},{"id":"d","label":"Parce que le P/E est illégal"}]'::jsonb, 'a', 'P/E 30 = cher (utility) vs normal (tech croissance). Le contexte sectoriel est essentiel.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.4-Q14', 'analyse-fondamentale', 'outils', 3, 'La « valeur terminale » dans un DCF représente généralement :', '[{"id":"a","label":"10-20 % de la valorisation totale"},{"id":"b","label":"60-80 % de la valorisation totale"},{"id":"c","label":"0 % de la valorisation"},{"id":"d","label":"La dette nette"}]'::jsonb, 'b', 'La majeure partie de la valeur vient des flux lointains, d''où la sensibilité aux hypothèses.', true);
INSERT INTO question_bank_part_a (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, is_active) VALUES ('1.4-Q15', 'analyse-fondamentale', 'outils', 3, 'Pourquoi l''analyse fondamentale d''une banque diffère-t-elle de celle d''une entreprise tech ?', '[{"id":"a","label":"Parce que les banques n''ont pas de bilan"},{"id":"b","label":"Parce que les métriques clés sont différentes (NIM, CET1, provisions vs ARR, churn)"},{"id":"c","label":"Parce que les banques ne sont pas cotées"},{"id":"d","label":"Parce que l''AF ne s''applique pas aux banques"}]'::jsonb, 'b', 'Chaque secteur a ses propres ratios et drivers de valeur.', true);